<script setup>
import AppIcon from '../../Components/AppIcon.vue';
import ChevronText from '../../Components/ChevronText.vue';
import {csvPoolName} from '../../lib/csv-pool-name.js';
import {ref,watch} from 'vue';
import { useI18n } from "../../lib/i18n.js";
import LanguageSwitch from "../../Components/LanguageSwitch.vue";
const {t,locale}=useI18n();
import { Head, Link, useForm } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import Errors from '../../Components/Errors.vue';
const props=defineProps({preview:{type:Object,default:null},collections:{type:Array,default:()=>[]},pools:{type:Array,default:()=>[]},selectedPoolId:[Number,String]});
const form=useForm({pool_id:props.preview?.new_pool?'new':props.selectedPoolId??'',first_row_pool_name:Boolean(props.preview?.new_pool),new_pool_language:props.preview?.new_pool?.language??props.pools?.find(pool=>pool.id===Number(props.selectedPoolId))?.language??'en',new_pool_direction:props.preview?.new_pool?.text_direction??props.pools?.find(pool=>pool.id===Number(props.selectedPoolId))?.text_direction??'ltr',file:null,term_column:0,definition_column:1,note_column:2,has_header:true});
const newPoolName=ref(props.preview?.new_pool?.name??''),poolNameError=ref(''),readingPoolName=ref(false);
let fileRead=0,previousPoolId=props.selectedPoolId??'';
async function readPoolName(){
 const revision=++fileRead;newPoolName.value='';poolNameError.value='';readingPoolName.value=false;
 if(!form.first_row_pool_name||!form.file)return;
 if(form.file.size>2*1024*1024){poolNameError.value=t('Up to 2 MB · .csv or .txt');return;}
 readingPoolName.value=true;
 try{const text=await form.file.text();if(revision===fileRead)newPoolName.value=csvPoolName(text);}
 catch(error){if(revision===fileRead)poolNameError.value=t(error.message==='The first CSV row must contain only a pool name, up to 150 characters.'?error.message:'Could not read the CSV file. Choose it again.');}
 finally{if(revision===fileRead)readingPoolName.value=false;}
}
function chooseFile(event){form.file=event.target.files?.[0]??null;readPoolName();}
function togglePoolName(){
 if(form.first_row_pool_name){previousPoolId=form.pool_id;form.pool_id='new';}else form.pool_id=previousPoolId;
 readPoolName();
}
function matchesPreview(){
 if(form.first_row_pool_name)return form.pool_id==='new'&&Boolean(props.preview?.new_pool)&&newPoolName.value===props.preview.new_pool.name&&form.new_pool_language===props.preview.new_pool.language&&form.new_pool_direction===props.preview.new_pool.text_direction;
 return !props.preview?.new_pool&&Number(form.pool_id)===Number(props.preview?.pool_id);
}
const save=useForm({collection_id:''});
const previewDirty=ref(false);let mappingRevision=0;
watch(()=>[form.file,form.pool_id,form.term_column,form.definition_column,form.note_column,form.has_header,form.first_row_pool_name,form.new_pool_language,form.new_pool_direction],()=>{mappingRevision++;previewDirty.value=Boolean(props.preview);},{flush:'sync'});
function commitImport(){if(save.processing||form.processing||previewDirty.value||!props.preview?.preview_id||!matchesPreview())return;save.transform(data=>({collection_id:data.collection_id,pool_id:props.preview.pool_id,preview_id:props.preview.preview_id})).post('/imports/store');}
function upload(){if(form.processing||save.processing||readingPoolName.value||(form.first_row_pool_name&&!newPoolName.value))return;const revision=mappingRevision;previewDirty.value=true;form.transform(data=>({...data,pool_id:data.first_row_pool_name?null:data.pool_id})).post('/imports/preview',{forceFormData:true,onSuccess:()=>{previewDirty.value=revision!==mappingRevision;}});}
</script>
<template><Head :title="t('Import words')"/><AppLayout :title="t('Bring your words along.')" :subtitle="t('From a spreadsheet to your next study session.')"><template #actions><Link :href="selectedPoolId?`/word-pools/${selectedPoolId}`:'/words'" class="button secondary"><ChevronText :text="t(selectedPoolId?'← Back to pool':'← Word pools')"/></Link></template><div class="import-grid"><section class="panel"><span class="step-label">{{t("01 / UPLOAD & MAP")}}</span><h2>{{t("A CSV full of possibilities.")}}</h2><p class="muted">{{t("Choose a UTF-8 CSV with word and definition columns. A third personal-note column is optional; two-column files still work.")}}</p><form @submit.prevent="upload"><Errors :errors="form.errors"/><label>{{t('Target word pool')}}<select v-model="form.pool_id" required><option value="" disabled>{{t('Choose a word pool')}}</option><option v-if="form.first_row_pool_name" value="new">{{newPoolName || t('Choose a CSV file')}}</option><option v-for="pool in (form.first_row_pool_name?[]:pools)" :key="pool.id" :value="pool.id">{{pool.name}} ({{pool.language}})</option></select></label><label class="check"><input type="checkbox" v-model="form.first_row_pool_name" @change="togglePoolName"/>{{t('First row contains the new pool name')}}</label><p v-if="poolNameError" class="notice error" role="alert">{{poolNameError}}</p><p v-if="readingPoolName" class="muted small" role="status">{{t('Reading file…')}}</p><div v-if="form.first_row_pool_name" class="two-col"><label>{{t('Language code')}}<input v-model="form.new_pool_language" required maxlength="35" placeholder="en-US, pt-PT, tr"/></label><label>{{t('Text direction')}}<select v-model="form.new_pool_direction"><option value="ltr">{{t('Left to right (LTR)')}}</option><option value="rtl">{{t('Right to left (RTL)')}}</option></select></label></div><p v-if="form.first_row_pool_name" class="muted small">{{t('The first row names a new pool. Column headings, if enabled, are on the second row. The pool is created when you confirm the import.')}}</p><p v-if="!pools.length&&!form.first_row_pool_name" class="notice">{{t('Create a word pool before importing.')}} <Link href="/words">{{t('Word pools')}}</Link></p><label class="upload-zone"><span class="upload-icon"><AppIcon name="import"/></span><strong>{{form.file?.name || t('Choose a CSV file')}}</strong><small>{{t("Up to 2 MB · .csv or .txt")}}</small><input type="file" accept=".csv,.txt,text/csv,text/plain" @change="chooseFile" required/></label><div class="two-col"><label>{{t("Word column")}}<select v-model.number="form.term_column"><option v-for="n in 20" :key="n" :value="n-1">{{t('Column')}} {{n}}</option></select></label><label>{{t("Definition column")}}<select v-model.number="form.definition_column"><option v-for="n in 20" :key="n" :value="n-1">{{t('Column')}} {{n}}</option></select></label><label>{{t('Personal note column (optional)')}}<select v-model="form.note_column"><option :value="null">{{t('Ignore notes')}}</option><option v-for="n in 20" :key="n" :value="n-1">{{t('Column')}} {{n}}</option></select></label></div><p class="muted small">{{t('Nonempty imported notes update your personal note. Blank or missing notes keep your existing note.')}}</p><label class="check"><input type="checkbox" v-model="form.has_header"/> {{t(form.first_row_pool_name?'Second row contains column headings':'First row contains column headings')}}</label><div class="form-actions"><button class="button" :disabled="form.processing||save.processing||!form.pool_id||readingPoolName||(form.first_row_pool_name&&!newPoolName)"><ChevronText :text="form.processing?t('Reading file…'):t('Preview import →')"/></button></div></form></section><aside class="import-help"><span class="eyebrow">{{t("A SIMPLE START")}}</span><h3>{{t("Two required columns.")}}<br>{{t("One optional private note.")}}</h3><pre v-if="form.first_row_pool_name">{{t('My vocabulary')}}
term,definition,note
curious,eager to learn,meraklı
resilient,able to recover,</pre><pre v-else>term,definition,note
curious,eager to learn,meraklı
resilient,able to recover,</pre><p>{{t("Imports match within the selected pool. Shared word changes affect every pool and collection using that word. Only your own private note can be updated; collection links are preserved.")}}</p><p>{{t("Matching ignores letter case and surrounding spaces, but keeps accents. Ambiguous matches are skipped with a warning.")}}</p></aside></div><p v-if="preview&&previewDirty" class="notice">{{t('The file or column mapping changed. Preview again before importing.')}}</p><p v-if="preview&&!matchesPreview()" class="notice">{{t('The target pool changed. Preview the file again before importing.')}}</p><section v-if="preview&&matchesPreview()&&!previewDirty" class="panel preview"><span class="step-label">{{t("02 / REVIEW & IMPORT")}}</span><div class="section-heading"><h2>{{t("Looking good?")}}</h2><span class="pill dark">{{preview.total}} {{t('rows')}} · {{preview.duplicates??0}} {{t('duplicates')}}</span></div><p class="muted">{{ t('{created} new · {updated} updated · {skipped} skipped', {created:preview.created??0,updated:preview.updated??0,skipped:preview.skipped??0}) }}</p><div v-if="preview.warnings?.length" class="notice" role="status"><strong>{{ t('Skipped rows need your review') }}</strong><ul><li v-for="(warning,index) in preview.warnings" :key="index"><strong>{{warning.term}}</strong>: {{t(warning.message)}}</li></ul></div><p v-if="preview.headers?.length"  class="muted small">{{t('Columns:')}} {{preview.headers.join(' · ')}}</p><div class="preview-table"><table><thead><tr><th>{{t("Word")}}</th><th>{{t("Definition")}}</th><th>{{t("Your private note")}}</th><th>{{t("Action")}}</th></tr></thead><tbody><tr v-for="(row,index) in preview.rows" :key="index"><td><bdi dir="auto">{{row.term}}</bdi></td><td><bdi dir="auto">{{row.definition}}</bdi></td><td><template v-if="row.note!==null&&row.note!==undefined&&row.note!==''"><bdi dir="auto" class="imported-note">{{row.note}}</bdi><small>{{t('Set private note')}}</small></template><small v-else>{{t(row.action==='create'?'No note':'Keep existing note')}}</small></td><td>{{t(row.action==='update'?'Update word':row.action==='unchanged'?'Keep existing':'Create word')}}</td></tr></tbody></table></div><p class="muted small">{{t('Preview may show only the first rows. The validated import contains {count} rows.',{count:preview.total})}}</p><form @submit.prevent="commitImport"><Errors :errors="save.errors"/><label v-if="collections.length">{{t("Also add to a collection")}}<select v-model="save.collection_id"><option value="">{{t("Word pool only")}}</option><option v-for="c in collections" :key="c.id" :value="c.id">{{c.title}}</option></select></label><div class="form-actions"><button class="button" :disabled="save.processing||form.processing||previewDirty||!preview.total||!preview.preview_id">{{save.processing?t('Importing…'):t('Import into my pool')}}</button></div></form></section></AppLayout></template>

<style scoped>.imported-note{display:block;white-space:pre-wrap;overflow-wrap:anywhere}.preview-table td small{display:block;color:var(--muted,#536a68);margin-top:5px}.preview-table bdi{unicode-bidi:isolate}.preview-table td{vertical-align:top}</style>
